const config = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "mysql",
  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Get a free hosted Postgres database in seconds: `npx create-db`\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n}\n\nmodel User {\n  id          String     @id @default(uuid())\n  clerkUserId String     @unique\n  nom         String\n  prenoms     String\n  email       String     @unique\n  telephone   String\n  statut      UserStatut\n\n  ecole Ecole[]\n\n  parent      Parent[]\n  apprenant   Apprenant?\n  employe     Employe[]\n  particpants ParticipantConversation[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n}\n\nenum UserStatut {\n  ACTIF\n  SUSPENDU\n  DESACTIVE\n  DOIT_MODIFIER_MDP\n}\n\n//défini un établissement dans sa globalité\nmodel Ecole {\n  id           String      @id @default(uuid())\n  nom          String\n  type         EcoleType\n  nomFondateur String\n  ville        String\n  boitePostale String?     @unique\n  email        String      @unique\n  telephone    String\n  description  String?\n  statut       EcoleStatut @default(EN_ATTENTE)\n  code         String      @unique //permettra de manipuler les écoles de manière unique sans invoquer la clé primaire de Ecole\n\n  users                User[]\n  anneeScolaires       AnneeScolaire[]\n  niveauxScolaires     NiveauScolaire[]\n  typeEvaluations      TypeEvaluation[]\n  politiqueEvaluations PolitiqueEvaluation[]\n  matieres             Matiere[]\n  annonces             Annonce[]\n  conversations        Conversation[]\n  configScolarite      ConfigurationScolarite[]\n\n  createdAt DateTime @default(now())\n  valideAt  DateTime\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@index([ville])\n}\n\nenum EcoleType {\n  MATERNELLE_PRIMAIRE\n  COLLEGE_LYCEE\n  UNIVERSITE\n}\n\nenum EcoleStatut {\n  EN_ATTENTE\n  ACTIF\n  SUSPENDU\n  DESACTIVE\n}\n\n//Rôle Métier attribuable à un employé\nmodel Role {\n  id          String  @id @default(uuid())\n  nom         String\n  description String?\n  estSystem   Boolean @default(false)\n\n  employeRole    EmployeRole[]\n  rolePermission RolePermission[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@unique([nom])\n}\n\n//Association entre employé et rôle\nmodel EmployeRole {\n  employeId String\n  roleId    String\n\n  employe Employe @relation(fields: [employeId], references: [id], onDelete: Cascade)\n  role    Role    @relation(fields: [roleId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@id([employeId, roleId])\n  @@index([roleId])\n}\n\n//Permission du système\nmodel Permission {\n  id          String  @id @default(uuid())\n  code        String  @unique\n  nom         String\n  description String?\n\n  rolePermission RolePermission[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@index([nom])\n}\n\n//associationn entre rôle et permission : un rôle peut posséder plusieurs permissions et une permission peut appartenir à plusieurs rôles. \n//Pourquoi ne pas directement faire une association N:N entre rôle et permission\n//C'est pour plus tard ajouter des attributs pour traquer qui donne les permissions \n//et aussi faire des logs beaucoup plus précis.\nmodel RolePermission {\n  roleId       String\n  permissionId String\n\n  role       Role       @relation(fields: [roleId], references: [id], onDelete: Cascade)\n  permission Permission @relation(fields: [permissionId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@id([roleId, permissionId])\n  @@index([permissionId])\n}\n\n//définit les employés d'un établissement. prof, admin et autres\nmodel Employe {\n  id           String   @id @default(uuid())\n  matricule    String   @unique\n  dateEmbauche DateTime\n  clerkUserId  String   @unique\n\n  employeDocument       EmployeDocument[]\n  employeRole           EmployeRole[]\n  affectationEnseignant AffectationEnseignant[]\n  annonces              Annonce[]\n\n  user      User     @relation(fields: [clerkUserId], references: [clerkUserId], onDelete: Cascade)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n}\n\n//documents associés à un employés, voir DocumentType pour détails\nmodel EmployeDocument {\n  id          String       @id @default(uuid())\n  employeId   String\n  type        DocumentType\n  titre       String\n  documentUrl String\n\n  employe Employe @relation(fields: [employeId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@index([employeId])\n}\n\nenum DocumentType {\n  DIPLOME\n  CONTRAT\n  PIECE_IDENTITE\n  JUSTIFICATIF\n}\n\n//définit un parent. Il peut avoir plusieurs élèves\nmodel Parent {\n  id         String @id @default(uuid())\n  userId     String @unique\n  profession String\n\n  user            User              @relation(fields: [userId], references: [id], onDelete: Cascade)\n  apprenantParent ApprenantParent[]\n\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n}\n\n//définit un apprenant\n//ecoleId a été enlevé volontairement car on peut déjà la trouver dans inscription\n//les relations entre un apprenant et son école dépendent surtout de l'inscription \n//et non de l'entité apprenant.\nmodel Apprenant {\n  id            String   @id @default(uuid())\n  userId        String?  @unique\n  matricule     String   @unique\n  nom           String\n  prenoms       String\n  Sexe          Sexe\n  dateNaissance DateTime\n\n  user         User?             @relation(fields: [userId], references: [id], onDelete: Cascade)\n  parents      ApprenantParent[]\n  inscriptions Inscription[] // un apprenant a plusieurs inscriptions dans le temps. \n  //Cette relation ne sert pas à prouver l'unicité de l'inscription d'un apprenant dans une école au cours d'une année scolaire        \n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@index([userId])\n  @@index([matricule])\n}\n\nenum Sexe {\n  MASCULIN\n  FEMININ\n}\n\n//liason entre apprenant et parent (plusieurs parents possibles)\nmodel ApprenantParent {\n  apprenantId String\n  parentId    String\n  lien        lienParente\n\n  parent    Parent    @relation(fields: [parentId], references: [id], onDelete: Cascade)\n  apprenant Apprenant @relation(fields: [apprenantId], references: [id], onDelete: Cascade)\n\n  @@id([apprenantId, parentId])\n  @@index([parentId])\n}\n\nenum lienParente {\n  PERE\n  MERE\n  TUTEUR\n}\n\n//Annee Scolaire\nmodel AnneeScolaire {\n  id        String      @id @default(uuid())\n  ecoleId   String\n  nom       String //ex \"2026-2027\", faire les validations en dto\n  dateDebut DateTime\n  dateFin   DateTime\n  statut    AnneeStatut @default(EN_PREPARATION)\n\n  ecole           Ecole                    @relation(fields: [ecoleId], references: [id])\n  inscription     Inscription[]\n  periodeScolaire PeriodeScolaire[]\n  affectation     AffectationEnseignant[]\n  politiqueEval   PolitiqueEvaluation[]\n  configScolarite ConfigurationScolarite[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@unique([nom, ecoleId]) //Pas deux fois la même année Scolaire dans la même écoele\n  @@index([ecoleId])\n}\n\nenum AnneeStatut {\n  EN_COURS\n  EN_PREPARATION\n  TERMINEE\n  ARCHIVEE\n}\n\n//Période (trimestre ou semestre) d'une année Scolaire\nmodel PeriodeScolaire {\n  id              String        @id @default(uuid())\n  annneScolaireId String\n  nom             String //1er Trimestres ...\n  ordre           Int //important pour savoir qu'est-ce qui vient avant et après\n  dateDebut       DateTime\n  dateFin         DateTime\n  statut          PeriodeStatut\n\n  anneeScolaire AnneeScolaire @relation(fields: [annneScolaireId], references: [id], onDelete: Cascade)\n  bulletin      Bulletin[]\n  note          Note[]\n  evaluations   Evaluation[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@index([annneScolaireId])\n}\n\nenum PeriodeStatut {\n  NON_COMMENCEE\n  OUVERTE\n  CLOTUREE\n  ARCHIVEE\n}\n\n//Niveau scolaire = Classe (ex: Terminale, 1er Année, Marternelle 1 ...)\nmodel NiveauScolaire {\n  id      String @id @default(uuid())\n  ecoleId String\n  nom     String\n\n  ecole           Ecole                    @relation(fields: [ecoleId], references: [id], onDelete: Cascade)\n  classeScolaire  ClassScolaire[]\n  configScolarite ConfigurationScolarite[]\n  createdAt       DateTime                 @default(now())\n\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@unique([nom, ecoleId])\n  @@index([ecoleId])\n}\n\nmodel ClassScolaire {\n  id               String @id @default(uuid())\n  niveauScolaireId String\n  nom              String //ClasseScolaire = Salle (ex: Terminale C, 1er Année Groupe 2, Maternelle 1-A)\n  capacite         Int\n  emploiDuTempsId  String @unique\n\n  niveauScolaire        NiveauScolaire          @relation(fields: [niveauScolaireId], references: [id], onDelete: Cascade)\n  inscription           Inscription[]\n  affectationEnseignant AffectationEnseignant[]\n  emploiDuTemps         EmploiDuTemps           @relation(fields: [emploiDuTempsId], references: [id], onDelete: Cascade)\n  classeMatiere         ClasseMatirere[]\n  PolitiqueEval         PolitiqueEvaluation?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@unique([niveauScolaireId, nom]) //pas deux classe avec le même nom dans un niveau\n  @@index([niveauScolaireId])\n}\n\n//les matières\nmodel Matiere {\n  id          String  @id @default(uuid())\n  ecoleId     String\n  nom         String\n  CodeMat     String //ex: Fr pour Français, MATHS pour Mathématiques\n  description String? //décrire un peu en quoi consiste la matière\n\n  ecole                 Ecole                   @relation(fields: [ecoleId], references: [id], onDelete: Cascade)\n  affectationEnseignant AffectationEnseignant[]\n  matiereUe             MatiereUe[]\n  classeMatiere         ClasseMatirere[]\n  ligneBulletin         LigneBulletin[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@unique([nom, ecoleId])\n  @@index([ecoleId])\n}\n\n//defini les UE\nmodel UniteEnseignement {\n  id           String           @id @default(uuid())\n  nom          String // nom de l'UE\n  code         String           @unique\n  coefficient  Int //Coeffiecient total de l'ue\n  matiereUe    MatiereUe[]\n  claseMatiere ClasseMatirere[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n}\n\n//laison de matirer dans une Ue\nmodel MatiereUe {\n  uniteEnseignementId String\n  matiereId           String\n  coefficient         Int //coefficient de la matiere dans l'UE\n\n  ue      UniteEnseignement @relation(fields: [uniteEnseignementId], references: [id], onDelete: Cascade)\n  matiere Matiere           @relation(fields: [matiereId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@id([uniteEnseignementId, matiereId])\n}\n\n//laison Classe Matiere (Fr en Terminale A)\nmodel ClasseMatirere {\n  id                  String  @id @default(uuid())\n  classeScolaireId    String\n  matiereId           String\n  uniteEnseignementId String?\n  coefficient         Int\n\n  classeScolaire    ClassScolaire      @relation(fields: [classeScolaireId], references: [id], onDelete: Cascade)\n  matiere           Matiere            @relation(fields: [matiereId], references: [id], onDelete: Cascade)\n  uniteEnseignement UniteEnseignement? @relation(fields: [uniteEnseignementId], references: [id])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@unique([classeScolaireId, matiereId])\n  @@index([classeScolaireId])\n}\n\n//Affectation d'un enseignant à une classe pour une matière et année\nmodel AffectationEnseignant {\n  id               String @id @default(uuid())\n  employeId        String\n  classeScolaireId String\n  matiereId        String\n  anneeScolaireId  String\n\n  employe        Employe         @relation(fields: [employeId], references: [id], onDelete: Cascade)\n  classeScolaire ClassScolaire   @relation(fields: [classeScolaireId], references: [id], onDelete: Cascade)\n  matiere        Matiere         @relation(fields: [matiereId], references: [id], onDelete: Cascade)\n  anneeScolaire  AnneeScolaire   @relation(fields: [anneeScolaireId], references: [id], onDelete: Cascade)\n  cours          EmploiDuTemps[]\n  evaluations    Evaluation[]\n  note           Note[]\n  absences       Absence[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@unique([matiereId, classeScolaireId, anneeScolaireId]) //Une matière par classe par annee a 1 seul enseignant\n  @@index([employeId])\n  @@index([anneeScolaireId])\n}\n\n// Emploi du temps (créneaux) pour une affectation\nmodel EmploiDuTemps {\n  id                      String      @id @default(uuid())\n  affectationEnseignantId String\n  jourDeLaSemaine         JourSemaine\n  heureDebut              String //fera la validation en dto\n  heureFin                String\n  classeScolaireId        String\n\n  affectationEnseignant AffectationEnseignant @relation(fields: [affectationEnseignantId], references: [id], onDelete: Cascade)\n  classeScolaire        ClassScolaire?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@unique([affectationEnseignantId, jourDeLaSemaine, heureDebut])\n}\n\nenum JourSemaine {\n  LUNDI\n  MARDI\n  MERCREDI\n  JEUDI\n  VENDREDI\n  SAMEDI\n  DIMANCHE\n}\n\n// Type d’évaluation (catégorie), défini par l’école\nmodel TypeEvaluation {\n  id      String @id @default(uuid())\n  ecoleId String\n  nom     String //ex: Interro 1\n\n  ecole       Ecole             @relation(fields: [ecoleId], references: [id], onDelete: Cascade)\n  evaluations Evaluation[]\n  regleEval   RegleEvaluation[]\n  notes       Note[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@unique([ecoleId, nom])\n}\n\n// Politique de calcul des notes pour une classe/année\nmodel PolitiqueEvaluation {\n  id               String         @id @default(uuid())\n  ecoleId          String\n  anneeScolaireId  String\n  classeScolaireId String?        @unique\n  nom              String //servira à identifier sur l'interface la politique d'évaluation. C'est surtout pratique quand une école en a plusieurs\n  methodeCalcul    MethodeCalcul // permet de savoir si on doit faire avec ou sans coefficient et si oui, le coefficient est appliqué ou? matière ou notes\n  methodeArrondi   MethodeArrondi //permet de savoir si on veut 15 ou 15.68 ou le réel\n  afficherRang     Boolean        @default(true)\n  estActive        Boolean        @default(true) //une école peut avoir plusieurs politiques mais n'en utiliser qu'une seule\n\n  ecole          Ecole             @relation(fields: [ecoleId], references: [id], onDelete: Cascade)\n  anneeScolaire  AnneeScolaire     @relation(fields: [anneeScolaireId], references: [id], onDelete: Cascade)\n  classeScolaire ClassScolaire?    @relation(fields: [classeScolaireId], references: [id], onDelete: Cascade)\n  regles         RegleEvaluation[] // Détails (nb d'épreuves et coef par type)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@unique([nom, ecoleId])\n  @@index([ecoleId])\n  @@index([anneeScolaireId])\n  @@index([classeScolaireId])\n}\n\n// Règle d'évaluation dans une politique (nb min d’épreuves et coefficient)\nmodel RegleEvaluation {\n  id              String @id @default(uuid())\n  nombreMin       Int    @default(0) // Nb minimum d'épreuves\n  coefficientType Int    @default(1) // Coefficient appliqué à ce type (si moyenne pondérée)\n\n  politiqueId      String\n  typeEvaluationId String\n\n  politique      PolitiqueEvaluation @relation(fields: [politiqueId], references: [id], onDelete: Cascade)\n  typeEvaluation TypeEvaluation      @relation(fields: [typeEvaluationId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@unique([politiqueId, typeEvaluationId])\n  @@index([politiqueId])\n  @@index([typeEvaluationId])\n}\n\n/// Évaluation (devoir, interro, contrôle), créée par un enseignant pour une classe\nmodel Evaluation {\n  id    String   @id @default(uuid())\n  titre String //Devoir 1 Maths\"\n  date  DateTime\n\n  affectationId     String\n  typeEvaluationId  String\n  periodeScolaireId String\n\n  affectation     AffectationEnseignant @relation(fields: [affectationId], references: [id], onDelete: Cascade)\n  typeEvaluation  TypeEvaluation        @relation(fields: [typeEvaluationId], references: [id], onDelete: Cascade)\n  periodeScolaire PeriodeScolaire       @relation(fields: [periodeScolaireId], references: [id], onDelete: Cascade)\n\n  notes Note[] // Toutes les notes des élèves pour cette évaluation\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@index([affectationId])\n  @@index([periodeScolaireId])\n}\n\nenum MethodeCalcul {\n  MOYENNE_SIMPLE\n  MOYENNE_PONDEREE\n}\n\nenum MethodeArrondi {\n  AUCUN\n  ENTIER\n  DIXIEME\n  CENTIEME\n}\n\n//Note obtenue par un élève à une évaluation\nmodel Note {\n  id          String @id @default(uuid())\n  Valeur      Float\n  Observation String //le prof peut laisser une observation sur la note que le parent verra\n  noteSur     Int    @default(20)\n\n  inscriptionApprenantId  String\n  inscriptionAnneeId      String\n  affectationEnseignantId String\n  typeEvaluationId        String\n  periodeScolaireId       String\n  evaluationId            String\n\n  inscription     Inscription           @relation(fields: [inscriptionApprenantId, inscriptionAnneeId], references: [apprenantId, anneeScolaireId], onDelete: Cascade)\n  affectation     AffectationEnseignant @relation(fields: [affectationEnseignantId], references: [id], onDelete: Cascade)\n  typeEvaluation  TypeEvaluation        @relation(fields: [typeEvaluationId], references: [id], onDelete: Cascade)\n  periodeScolaire PeriodeScolaire       @relation(fields: [periodeScolaireId], references: [id], onDelete: Cascade)\n  evaluation      Evaluation            @relation(fields: [evaluationId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@index([inscriptionApprenantId, inscriptionAnneeId])\n  @@index([affectationEnseignantId])\n  @@index([typeEvaluationId])\n  @@index([periodeScolaireId])\n}\n\n//inscription d'un apprenant dans une école, année, classe.\nmodel Inscription {\n  matricule       String?         @unique\n  dateInscription DateTime        @default(now())\n  type            InscriptionType\n\n  apprenantId              String\n  anneeScolaireId          String\n  classeScolaireId         String\n  configuartionScolariteId String //frais de scolarité de l'apprenant\n\n  apprenant              Apprenant              @relation(fields: [apprenantId], references: [id], onDelete: Cascade)\n  anneeScolaire          AnneeScolaire          @relation(fields: [anneeScolaireId], references: [id], onDelete: Cascade)\n  classeScolaire         ClassScolaire          @relation(fields: [classeScolaireId], references: [id], onDelete: Cascade)\n  configurationScolarite ConfigurationScolarite @relation(fields: [configuartionScolariteId], references: [id], onDelete: Cascade)\n  dossierScolarite       DossierScolarite?\n  decisionFinale         DecisionFinAnnee?\n\n  bulletins Bulletin[] //plusieurs bulletins mais un par période\n  notes     Note[] //Note d'un apprenant. Notons qu'une note n'est reliée à un bulletin que si l'admin lance la génération\n  absences  Absence[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@id([apprenantId, anneeScolaireId])\n  @@unique([apprenantId, classeScolaireId])\n  @@index([classeScolaireId, anneeScolaireId])\n}\n\nenum InscriptionType {\n  INSCRIPTION\n  REINSCRIPTION\n  TRANSFERT_EN_COURS_D_ANNEE\n}\n\n//bulletin scolaire par apprenant et par période scolaire\nmodel Bulletin {\n  moyenneGenerale  Float\n  documentUrl      String\n  Rang             Int? //classement par classe\n  estGenere        Boolean              @default(false)\n  dateGeneration   DateTime?\n  appreciation     String?\n  decisionFinAnnee DecisionFinAnneeType\n\n  inscriptionApprenantId String\n  inscriptionAnneeId     String\n  periodeScolaireId      String\n\n  inscription     Inscription     @relation(fields: [inscriptionApprenantId, inscriptionAnneeId], references: [apprenantId, anneeScolaireId], onDelete: Cascade)\n  periodeScolaire PeriodeScolaire @relation(fields: [periodeScolaireId], references: [id], onDelete: Cascade)\n  lignes          LigneBulletin[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@id([inscriptionApprenantId, inscriptionAnneeId, periodeScolaireId])\n  @@index([periodeScolaireId])\n}\n\n// Détail par matière sur le bulletin (moyenne et coef)\nmodel LigneBulletin {\n  id                  String @id @default(uuid())\n  bulletinId          String\n  bulletinApprenantId String\n  bulletinAnneeId     String\n  matiereId           String\n  moyenne             Float\n  coefficient         Int\n\n  bulletin Bulletin @relation(fields: [bulletinApprenantId, bulletinAnneeId, bulletinId], references: [inscriptionApprenantId, inscriptionAnneeId, periodeScolaireId], onDelete: Cascade)\n  matiere  Matiere  @relation(fields: [matiereId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@index([matiereId])\n}\n\n//Absence pour un apprenant\nmodel Absence {\n  id               String        @id @default(uuid())\n  dateDebut        DateTime\n  dateFin          DateTime\n  motif            String\n  statut           AbsenceStatut\n  commentaire      String?\n  declareParUserId String //celui qui déclare l'absence\n  justificatifUrl  String?\n\n  inscriptionApprenantId  String\n  inscriptionAnneeId      String\n  affectationEnseignantId String?\n\n  inscription           Inscription            @relation(fields: [inscriptionApprenantId, inscriptionAnneeId], references: [apprenantId, anneeScolaireId], onDelete: Cascade)\n  affectationEnseignant AffectationEnseignant? @relation(fields: [affectationEnseignantId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@index([inscriptionApprenantId, inscriptionAnneeId])\n}\n\nenum AbsenceStatut {\n  JUSTIFIEE\n  NON_JUSTIFIEE\n}\n\n//\nmodel ConfigurationScolarite {\n  id        String  @id @default(uuid())\n  nom       String //ex: Scolarité Terminale 2026\n  estActive Boolean @default(true)\n\n  ecoleId          String\n  niveauScolaireId String\n  anneeScolaireId  String\n\n  ecole            Ecole              @relation(fields: [ecoleId], references: [id], onDelete: Cascade)\n  niveauScolaire   NiveauScolaire     @relation(fields: [niveauScolaireId], references: [id], onDelete: Cascade)\n  anneeScolaire    AnneeScolaire      @relation(fields: [anneeScolaireId], references: [id], onDelete: Cascade)\n  inscription      Inscription[]\n  tranches         TrancheScolarite[]\n  dossierScolarite DossierScolarite[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@unique([niveauScolaireId, anneeScolaireId]) //une seule config par niveau scolaire et non par classe\n}\n\n// Tranche de paiement liée à une configuration de scolarité\nmodel TrancheScolarite {\n  id           String   @id @default(uuid())\n  nom          String\n  montant      Int\n  dateEcheance DateTime\n  ordre        Int\n\n  configurationScolariteId String\n\n  configurationScolarite ConfigurationScolarite @relation(fields: [configurationScolariteId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  //ex: 1ere tranche :100.000 fcfa avant le 30/10/2027\n\n  @@index([configurationScolariteId])\n}\n\n// Dossier de scolarité (suivi des paiements) pour une inscription\nmodel DossierScolarite {\n  id          String                 @id @default(uuid())\n  montant     Int\n  resteAPayer Int\n  statut      DossierScolariteStatut\n\n  inscriptionApprenantId   String\n  inscriptionAnneeId       String\n  configurationScolariteId String\n\n  inscription            Inscription            @relation(fields: [inscriptionApprenantId, inscriptionAnneeId], references: [apprenantId, anneeScolaireId], onDelete: Cascade)\n  configurationScolarite ConfigurationScolarite @relation(fields: [configurationScolariteId], references: [id], onDelete: Cascade)\n  paiements              Paiement[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@unique([inscriptionApprenantId, inscriptionAnneeId])\n  @@index([inscriptionApprenantId, inscriptionAnneeId])\n}\n\nenum DossierScolariteStatut {\n  A_JOUR\n  EN_RETARD\n  SOLDEE\n}\n\n//Paiement effectué sur un dossier de scolarité\nmodel Paiement {\n  id            String        @id @default(uuid())\n  montant       Int\n  datePaiement  DateTime\n  moyenPaiement MoyenPaiement\n  references    String?\n  recuUrl       String?\n\n  dossierScolariteId String\n\n  dossierScolarite DossierScolarite @relation(fields: [dossierScolariteId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@index([dossierScolariteId])\n}\n\nenum MoyenPaiement {\n  BANQUE\n  MOBILE_MONEY\n  ESPECES\n}\n\n//Annonce diffusée (privée ou publique)\nmodel Annonce {\n  id             String   @id @default(uuid())\n  titre          String\n  contenu        String\n  datePubication DateTime @default(now())\n  dateExpiration DateTime\n\n  ecoleId  String\n  auteurId String\n\n  ecole       Ecole          @relation(fields: [ecoleId], references: [id], onDelete: Cascade)\n  employe     Employe        @relation(fields: [auteurId], references: [id], onDelete: Cascade)\n  cibleAnnoce CibleAnnonce[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@index([ecoleId])\n}\n\nmodel CibleAnnonce {\n  id     String        @id @default(uuid())\n  public PublicAnnonce\n\n  annonceId        String\n  classeScolaireId String?\n\n  annonce Annonce @relation(fields: [annonceId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@index([annonceId])\n}\n\nenum PublicAnnonce {\n  TOUS\n  EMPLOYE\n  PARENT\n  APPRENANT\n}\n\n//Conversation pour échanges de messages\nmodel Conversation {\n  id   String           @id @default(uuid())\n  type ConversationType\n\n  ecoleId String\n\n  ecole       Ecole                     @relation(fields: [ecoleId], references: [id], onDelete: Cascade)\n  particpants ParticipantConversation[]\n  messages    Message[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@index([ecoleId])\n}\n\nenum ConversationType {\n  PRIVEE\n  GROUPE\n}\n\n// Participant d'une conversation (user ↔ conversation)\nmodel ParticipantConversation {\n  conversationId String\n  userId         String\n\n  conversation Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  user         User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@id([conversationId, userId])\n  @@index([userId])\n}\n\n// Message dans une conversation\nmodel Message {\n  id         String   @id @default(uuid())\n  contenu    String\n  fichierUrl String?\n  dateEnvoi  DateTime @default(now())\n  lu         Boolean  @default(false)\n\n  conversationId String\n\n  conversation Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@index([conversationId])\n  @@index([conversationId, dateEnvoi])\n}\n\n// Décision de fin d'année pour un apprenant\nmodel DecisionFinAnnee {\n  id       String               @id @default(uuid())\n  decision DecisionFinAnneeType\n\n  inscriptionApprenantId String\n  inscriptionAnneeId     String\n\n  incscription Inscription @relation(fields: [inscriptionApprenantId, inscriptionAnneeId], references: [apprenantId, anneeScolaireId], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@unique([inscriptionApprenantId, inscriptionAnneeId])\n}\n\nenum DecisionFinAnneeType {\n  ADMIS\n  REDOUBLE\n  EXCLU\n  TRANSFERE\n}\n"
}

